WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_boat_basic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '顺逆流基础', 'kp-trv-boat-basic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "顺逆流基础（流水行船）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "顺水 = 船速 + 水速；逆水 = 船速 - 水速。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只要在江河湖海里开船，就必然受到水流的加成或阻碍。风向助推飞机也是同理。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "记住两个推论公式（用来解已知顺逆速度求静水速度）："}]}, {"type": "katexBlock", "attrs": {"content": "V_{船} = \\frac{V_{顺} + V_{逆}}{2} \\quad ; \\quad V_{水} = \\frac{V_{顺} - V_{逆}}{2}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目找出已知的速度] --> B{给的是单独速度还是顺逆速度?}\nB -- 单独船速水速 --> C[套用加减法算出 V顺 和 V逆]\nB -- 顺逆速度 --> D[套用除二公式算出静水 V船 和 V水]\nC --> E[利用 S=VT 解决后续的路程或时间问题]\nD --> E"}}]}$$ AS jsonb), NULL, '顺逆流基础的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "顺逆流基础"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_boat_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
